package engine

import "testing"

func TestURLPattern(t *testing.T) {
	tab := platformTab(t)
	runJSCases(t, tab, []jsCase{
		{"named group", `const r = new URLPattern({ pathname: '/foo/:bar' }).exec({ pathname: '/foo/baz' }); return [r.pathname.groups, r.pathname.input, r.inputs.length];`, `[{"bar":"baz"},"/foo/baz",1]`},
		{"named group does not cross segments", `const p = new URLPattern({ pathname: '/foo/:bar' }); return [p.test({ pathname: '/foo/a/b' }), p.test({ pathname: '/foo/' }), p.test({ pathname: '/foo' })];`, `[false,false,false]`},
		{"string input against pattern", `return new URLPattern({ pathname: '/books/:id' }).test('https://example.com/books/123');`, `true`},
		{"wildcard", `const r = new URLPattern({ pathname: '/books/*' }).exec('https://x.test/books/a/b'); return r.pathname.groups;`, `{"0":"a/b"}`},
		{"regexp group", `const p = new URLPattern({ pathname: '/post/(\\d+)' }); return [p.test({ pathname: '/post/42' }), p.test({ pathname: '/post/x' }), p.exec({ pathname: '/post/42' }).pathname.groups[0], p.hasRegExpGroups];`, `[true,false,"42",true]`},
		{"named regexp group", `const r = new URLPattern({ pathname: '/:id(\\d+)' }).exec({ pathname: '/7' }); return r.pathname.groups;`, `{"id":"7"}`},
		{"optional modifier", `const p = new URLPattern({ pathname: '/books/:id?' }); const a = p.exec({ pathname: '/books' }); const b = p.exec({ pathname: '/books/9' }); return [a.pathname.groups.id === undefined, 'id' in a.pathname.groups, b.pathname.groups.id];`, `[true,true,"9"]`},
		{"zero or more", `const p = new URLPattern({ pathname: '/files/:path*' }); return [p.exec({ pathname: '/files' }).pathname.groups.path === undefined, p.exec({ pathname: '/files/a/b/c' }).pathname.groups.path, p.test({ pathname: '/files/' })];`, `[true,"a/b/c",false]`},
		{"one or more", `const p = new URLPattern({ pathname: '/f/:n+' }); return [p.test({ pathname: '/f' }), p.exec({ pathname: '/f/a/b' }).pathname.groups.n];`, `[false,"a/b"]`},
		{"group braces", `const p = new URLPattern({ pathname: '/book{s}?' }); return [p.test({ pathname: '/book' }), p.test({ pathname: '/books' }), p.test({ pathname: '/bookz' })];`, `[true,true,false]`},
		{"group braces with prefix and name", `const p = new URLPattern({ pathname: '/api{/:v}?/x' }); return [p.test({ pathname: '/api/x' }), p.exec({ pathname: '/api/2/x' }).pathname.groups.v, p.pathname];`, `[true,"2","/api/:v?/x"]`},
		{"escaped colon", `const p = new URLPattern({ pathname: '/foo\\:bar' }); return [p.test({ pathname: '/foo:bar' }), p.pathname];`, `[true,"/foo\\:bar"]`},
		{"name stops at non name char", `const r = new URLPattern({ pathname: '/:foo-bar' }).exec({ pathname: '/a-bar' }); return r.pathname.groups;`, `{"foo":"a"}`},
		{"unnamed groups are numbered", `const r = new URLPattern({ pathname: '/(\\d+)/(.*)' }).exec({ pathname: '/12/x/y' }); return r.pathname.groups;`, `{"0":"12","1":"x/y"}`},
		{"baseURL in dictionary", `const p = new URLPattern({ pathname: '/x', baseURL: 'https://example.com' }); return [p.protocol, p.hostname, p.port, p.pathname, p.search, p.hash, p.username];`, `["https","example.com","","/x","*","*","*"]`},
		{"defaults are wildcards", `const p = new URLPattern({ pathname: '/x' }); return [p.protocol, p.username, p.password, p.hostname, p.port, p.search, p.hash];`, `["*","*","*","*","*","*","*"]`},
		{"constructor string", `const p = new URLPattern('https://example.com/foo/bar?q=1#h'); return [p.protocol, p.hostname, p.port, p.pathname, p.search, p.hash, p.username];`, `["https","example.com","","/foo/bar","q=1","h","*"]`},
		{"constructor string without search and hash", `const p = new URLPattern('https://example.com/foo'); return [p.pathname, p.search, p.hash];`, `["/foo","*","*"]`},
		{"constructor string with credentials and port", `const p = new URLPattern('https://user@example.com:8080/x'); return [p.username, p.password, p.hostname, p.port];`, `["user","*","example.com","8080"]`},
		{"constructor string with base", `const p = new URLPattern('../x', 'https://example.com/a/b/c'); return [p.protocol, p.hostname, p.pathname];`, `["https","example.com","/a/x"]`},
		{"constructor string relative needs base", `try { new URLPattern('/foo'); } catch (e) { return e.name; }`, `"TypeError"`},
		{"constructor string pathname only with base", `const p = new URLPattern('/books/:id', 'https://example.com'); return [p.test('https://example.com/books/3'), p.test('https://other.com/books/3')];`, `[true,false]`},
		{"non-special scheme", `const p = new URLPattern('data\\:text/*'); return [p.protocol, p.pathname, p.test('data:text/plain'), p.test('data:image/png')];`, `["data","text/*",true,false]`},
		{"search and hash groups", `const r = new URLPattern({ search: 'q=:v', hash: ':frag' }).exec('https://x.test/?q=7#top'); return [r.search.groups.v, r.hash.groups.frag];`, `["7","top"]`},
		{"hostname wildcard", `const p = new URLPattern({ hostname: '*.example.com' }); return [p.test('https://sub.example.com/'), p.test('https://example.com/'), p.exec('https://a.b.example.com/').hostname.groups[0]];`, `[true,false,"a.b"]`},
		{"hostname segment delimiter", `const p = new URLPattern({ hostname: ':sub.example.com' }); return [p.test('https://a.example.com'), p.test('https://a.b.example.com')];`, `[true,false]`},
		{"hostname is case-folded", `const p = new URLPattern({ hostname: 'EXAMPLE.com' }); return [p.hostname, p.test('https://example.com')];`, `["example.com",true]`},
		{"default port removed", `const p = new URLPattern({ protocol: 'https', port: '443' }); return [p.port, new URLPattern({ protocol: 'https', port: '8443' }).port, new URLPattern({ protocol: 'http', port: '8080' }).port];`, `["","8443","8080"]`},
		{"port matching", `const p = new URLPattern({ port: '8080' }); return [p.test('http://x.test:8080/'), p.test('http://x.test/')];`, `[true,false]`},
		{"ignoreCase", `const a = new URLPattern({ pathname: '/Foo' }, { ignoreCase: true }); const b = new URLPattern({ pathname: '/Foo' }); return [a.test({ pathname: '/foo' }), b.test({ pathname: '/foo' }), b.test({ pathname: '/Foo' })];`, `[true,false,true]`},
		{"normalised component strings", `return [new URLPattern({ pathname: '/foo/(.*)' }).pathname, new URLPattern({ pathname: '/:a/:b?' }).pathname, new URLPattern({ pathname: '/foo/:bar(\\d+)' }).pathname, new URLPattern({ pathname: '/foo/*' }).pathname, new URLPattern({ pathname: '/(a|b)' }).pathname, new URLPattern({ pathname: '/:a*' }).pathname];`, `["/foo/*","/:a/:b?","/foo/:bar(\\d+)","/foo/*","/(a|b)","/:a*"]`},
		{"pathname gets canonicalised", `return [new URLPattern({ pathname: '/a/../b' }).pathname, new URLPattern({ pathname: '/café' }).pathname];`, `["/b","/caf%C3%A9"]`},
		{"input is canonicalised before matching", `const p = new URLPattern({ pathname: '/caf%C3%A9' }); return [p.test({ pathname: '/café' }), p.test('https://x.test/café'), new URLPattern({ pathname: '/a/b' }).test({ pathname: '/a/c/../b' })];`, `[true,true,true]`},
		{"test with relative input and base", `return [new URLPattern({ pathname: '/a/b' }).test('b', 'https://x.test/a/'), new URLPattern({ pathname: '/a/b' }).exec('b', 'https://x.test/a/').inputs];`, `[true,["b","https://x.test/a/"]]`},
		{"init input with baseURL inheritance", `const p = new URLPattern({ hostname: 'x.test', pathname: '/a/b' }); return [p.test({ pathname: 'b', baseURL: 'https://x.test/a/' }), p.test({ pathname: 'b', baseURL: 'https://y.test/a/' })];`, `[true,false]`},
		{"invalid url input yields null", `const p = new URLPattern({}); return [p.exec('not a url'), p.test('::::')];`, `[null,false]`},
		{"empty pattern matches everything", `const p = new URLPattern(); return [p.test('https://x.test/anything'), p.exec({}).pathname.input];`, `[true,""]`},
		{"error: duplicate name", `try { new URLPattern({ pathname: '/:a/:a' }); } catch (e) { return e.name; }`, `"TypeError"`},
		{"error: bad regexp group", `const out = []; for (const s of ['/(?<x>a)', '/(', '/(a(b))', '/()']) { try { new URLPattern({ pathname: s }); out.push('ok'); } catch (e) { out.push(e.name); } } return out;`, `["TypeError","TypeError","TypeError","TypeError"]`},
		{"error: bad port", `const out = []; for (const s of ['abc', '70000', '-1']) { try { new URLPattern({ port: s }); out.push('ok'); } catch (e) { out.push(e.name); } } return out;`, `["TypeError","TypeError","TypeError"]`},
		{"error: bad protocol", `try { new URLPattern({ protocol: 'ht tp' }); } catch (e) { return e.name; }`, `"TypeError"`},
		{"error: baseURL with init and string base", `try { new URLPattern({ pathname: '/x' }, 'https://x.test'); } catch (e) { return e.name; }`, `"TypeError"`},
		{"error: baseURL invalid", `try { new URLPattern({ pathname: '/x', baseURL: 'nope' }); } catch (e) { return e.name; }`, `"TypeError"`},
		{"error: exec init with baseURL arg", `try { new URLPattern({}).exec({ pathname: '/x' }, 'https://x.test'); } catch (e) { return e.name; }`, `"TypeError"`},
		{"error: new required", `try { URLPattern({}); } catch (e) { return e.name; }`, `"TypeError"`},
		{"result shape", `const r = new URLPattern({ pathname: '/:a' }).exec('https://u:p@h.test:81/x?s=1#z'); return [Object.keys(r), r.username.input, r.password.input, r.hostname.input, r.port.input, r.search.input, r.hash.input, r.protocol.input];`, `[["inputs","protocol","username","password","hostname","port","pathname","search","hash"],"u","p","h.test","81","s=1","z","https"]`},
		{"regexp group with modifier and prefix", `const p = new URLPattern({ pathname: '/:rest(.*)?' }); return [p.test({ pathname: '/' }), p.exec({ pathname: '/a/b' }).pathname.groups.rest];`, `[true,"a/b"]`},
		{"toStringTag and hasRegExpGroups default", `const p = new URLPattern({ pathname: '/:a' }); return [String(p), p.hasRegExpGroups, typeof URLPattern.prototype.exec];`, `["[object URLPattern]",false,"function"]`},
		{"URL object as input", `return new URLPattern({ pathname: '/p/:x' }).exec(new URL('https://a.test/p/9')).pathname.groups.x;`, `"9"`},
	})
}
